def _bool_fact(facts, name):
    v = facts.get(name)
    if isinstance(v, bool):
        return v
    return None

def _number_fact(facts, name):
    v = facts.get(name)
    if isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        return v
    return None

def _actor(question):
    m = re.search(r"\bto\s+([A-Z][A-Za-z'-]*)", question)
    if m:
        return m.group(1)
    m = re.search(r"\b([A-Z][A-Za-z'-]*)'s\s+additional", question)
    if m:
        return m.group(1)
    return "the taxpayer"

def _is_c6a(question):
    return re.search(r"63\s*\(\s*c\s*\)\s*\(\s*6\s*\)\s*\(\s*A\s*\)", question, re.I) is not None

def _is_c3_amount(question):
    cited = re.search(r"63\s*\(\s*c\s*\)\s*\(\s*3\s*\)", question, re.I) is not None
    return cited and "additional standard deduction" in question.casefold()

def _negated(question):
    return re.search(r"\bnot\b|does\s+not|isn't|is\s+unequal", question, re.I) is not None

def _claim_amount(question):
    amounts = re.findall(r"\$\s*([0-9][0-9,]*(?:\.[0-9]+)?)", question)
    if amounts:
        raw = amounts[-1]
    else:
        m = re.search(r"(?:equal\s+to|equals|is)\s+([0-9][0-9,]*(?:\.[0-9]+)?)", question, re.I)
        if not m:
            return None
        raw = m.group(1)
    raw = raw.replace(",", "")
    if "." in raw:
        return float(raw)
    return int(raw)

def _invert(answer):
    if answer == "Entailment":
        return "Contradiction"
    if answer == "Contradiction":
        return "Entailment"
    return "unknown"

def _missing(facts, names):
    result = []
    for name in names:
        if facts.get(name) is None:
            result.append(name)
    return result

def _either_itemizes(taxpayer_itemizes, spouse_itemizes):
    if taxpayer_itemizes is True or spouse_itemizes is True:
        return True
    if taxpayer_itemizes is False and spouse_itemizes is False:
        return False
    return None

def _c6a_applies(facts):
    married = _bool_fact(facts, "married_at_close")
    separate = _bool_fact(facts, "filed_separate_return")
    itemizes = _either_itemizes(_bool_fact(facts, "taxpayer_itemized"), _bool_fact(facts, "spouse_itemized"))
    if married is False or separate is False or itemizes is False:
        return False
    if married is True and separate is True and itemizes is True:
        return True
    return None

def _and_tri(a, b):
    if a is False or b is False:
        return False
    if a is True and b is True:
        return True
    return None

def _age_65(facts, field):
    age = _number_fact(facts, field)
    if age is None:
        return None
    return age >= 65

def _spouse_exemption_allowed(facts):
    exists = _bool_fact(facts, "spouse_existed_for_exemption")
    joint = _bool_fact(facts, "joint_return_made")
    income = _number_fact(facts, "spouse_gross_income")
    dependent = _bool_fact(facts, "spouse_was_another_taxpayers_dependent")
    if exists is False or joint is True or dependent is True:
        return False
    if income is not None and income != 0:
        return False
    if exists is True and joint is False and income == 0 and dependent is False:
        return True
    return None

def _surviving_spouse(facts):
    death = _bool_fact(facts, "spouse_died_in_two_preceding_years")
    home = _bool_fact(facts, "maintained_home_for_dependent_child")
    cost = _bool_fact(facts, "furnished_over_half_household_cost")
    remarried = _bool_fact(facts, "remarried_before_year_end")
    joint_possible = _bool_fact(facts, "joint_return_possible_in_death_year")
    if death is False or home is False or cost is False or remarried is True or joint_possible is False:
        return False
    if death is True and home is True and cost is True and remarried is False and joint_possible is True:
        return True
    return None

def _rate_possibilities(facts):
    married = _bool_fact(facts, "married_at_close")
    surviving = _surviving_spouse(facts)
    if married is True:
        return set([600])
    if married is False:
        if surviving is True:
            return set([600])
        if surviving is False:
            return set([750])
        return set([600, 750])
    if surviving is True:
        return set([600])
    return set([600, 750])

def _event_values(value):
    if value is True:
        return [1]
    if value is False:
        return [0]
    return [0, 1]

def _event_counts(events):
    counts = set([0])
    for event in events:
        next_counts = set()
        for old in counts:
            for addend in _event_values(event):
                next_counts.add(old + addend)
        counts = next_counts
    return counts

def _given_additional_totals(facts):
    total = _number_fact(facts, "stated_additional_standard_deduction_total")
    if total is not None:
        return set([total]), ["R63_C3"]
    amount_fields = [
        "stated_f1a_self_aged_amount",
        "stated_f1b_spouse_aged_amount",
        "stated_f2a_self_blind_amount",
        "stated_f2b_spouse_blind_amount"
    ]
    entitlement_fields = [
        "stated_f1a_self_aged_entitlement",
        "stated_f1b_spouse_aged_entitlement",
        "stated_f2a_self_blind_entitlement",
        "stated_f2b_spouse_blind_entitlement"
    ]
    fixed = 0
    unpriced_count = 0
    disclosed = False
    used_f1 = False
    used_f2 = False
    for i in range(4):
        amount = _number_fact(facts, amount_fields[i])
        entitled = _bool_fact(facts, entitlement_fields[i])
        if amount is not None:
            fixed += amount
            disclosed = True
            if i < 2:
                used_f1 = True
            else:
                used_f2 = True
        elif entitled is not None:
            disclosed = True
            if entitled is True:
                unpriced_count += 1
                if i < 2:
                    used_f1 = True
                else:
                    used_f2 = True
    if not disclosed:
        return None, []
    totals = set()
    if unpriced_count == 0:
        totals.add(fixed)
    else:
        for rate in _rate_possibilities(facts):
            totals.add(fixed + rate * unpriced_count)
    rule_ids = ["R63_C3"]
    if used_f1:
        rule_ids.append("R63_F1")
    if used_f2:
        rule_ids.append("R63_F2")
    if unpriced_count > 0:
        rule_ids.append("R63_F3")
    return totals, rule_ids

def _raw_additional_totals(facts):
    exemption = _spouse_exemption_allowed(facts)
    events = [
        _age_65(facts, "taxpayer_age_at_year_end"),
        _bool_fact(facts, "taxpayer_blind_at_year_end"),
        _and_tri(_age_65(facts, "spouse_age_at_year_end"), exemption),
        _and_tri(_bool_fact(facts, "spouse_blind_at_relevant_time"), exemption)
    ]
    totals = set()
    for rate in _rate_possibilities(facts):
        for count in _event_counts(events):
            totals.add(rate * count)
    return totals

def _additional_totals(facts):
    given, rule_ids = _given_additional_totals(facts)
    if given is not None:
        return given, rule_ids, True
    return _raw_additional_totals(facts), ["R63_C3", "R63_F1", "R63_F2", "R63_F3", "R151_B", "R2_SURVIVING"], False

def _c6_plan(actor):
    return {
        "supported": True,
        "fields": {
            "married_at_close": {"type": "boolean", "question": "Was " + actor + " married at the close of the taxable year?"},
            "filed_separate_return": {"type": "boolean", "question": "Did " + actor + " file a separate return for the taxable year?"},
            "taxpayer_itemized": {"type": "boolean", "question": "Did " + actor + " itemize deductions for the taxable year?"},
            "spouse_itemized": {"type": "boolean", "question": "Did " + actor + "'s spouse itemize deductions for the taxable year?"}
        }
    }

def _amount_plan(actor):
    return {
        "supported": True,
        "fields": {
            "stated_additional_standard_deduction_total": {"type": "number", "question": "What total additional standard deduction amount does the case explicitly state for " + actor + "?"},
            "stated_f1a_self_aged_amount": {"type": "number", "question": "What dollar amount does the case explicitly state " + actor + " is entitled to for " + actor + " under section 63(f)(1)(A)?"},
            "stated_f1b_spouse_aged_amount": {"type": "number", "question": "What dollar amount does the case explicitly state " + actor + " is entitled to for the spouse under section 63(f)(1)(B)?"},
            "stated_f2a_self_blind_amount": {"type": "number", "question": "What dollar amount does the case explicitly state " + actor + " is entitled to under section 63(f)(2)(A)?"},
            "stated_f2b_spouse_blind_amount": {"type": "number", "question": "What dollar amount does the case explicitly state " + actor + " is entitled to for the spouse under section 63(f)(2)(B)?"},
            "stated_f1a_self_aged_entitlement": {"type": "boolean", "question": "Does the case explicitly state that " + actor + " is entitled to an additional amount under section 63(f)(1)(A)?"},
            "stated_f1b_spouse_aged_entitlement": {"type": "boolean", "question": "Does the case explicitly state that " + actor + " is entitled to an additional amount for the spouse under section 63(f)(1)(B)?"},
            "stated_f2a_self_blind_entitlement": {"type": "boolean", "question": "Does the case explicitly state that " + actor + " is entitled to an additional amount under section 63(f)(2)(A)?"},
            "stated_f2b_spouse_blind_entitlement": {"type": "boolean", "question": "Does the case explicitly state that " + actor + " is entitled to an additional amount for the spouse under section 63(f)(2)(B)?"},
            "married_at_close": {"type": "boolean", "question": "Was " + actor + " married at the close of the taxable year?"},
            "spouse_died_in_two_preceding_years": {"type": "boolean", "question": "Did " + actor + "'s spouse die during either of the two years immediately preceding the taxable year?"},
            "maintained_home_for_dependent_child": {"type": "boolean", "question": "Did " + actor + " maintain a home that was the taxable-year principal abode of a dependent son, stepson, daughter, or stepdaughter?"},
            "furnished_over_half_household_cost": {"type": "boolean", "question": "Did " + actor + " furnish over half the cost of maintaining that household during the taxable year?"},
            "remarried_before_year_end": {"type": "boolean", "question": "Had " + actor + " remarried before the close of the taxable year?"},
            "joint_return_possible_in_death_year": {"type": "boolean", "question": "Could " + actor + " and the deceased spouse have made a joint return for the taxable year in which the spouse died?"},
            "taxpayer_age_at_year_end": {"type": "integer", "question": "What was " + actor + "'s age at the close of the taxable year?"},
            "taxpayer_blind_at_year_end": {"type": "boolean", "question": "Was " + actor + " blind at the close of the taxable year?"},
            "spouse_existed_for_exemption": {"type": "boolean", "question": "Did " + actor + " have a spouse during the taxable year for whom spouse facts are stated?"},
            "spouse_age_at_year_end": {"type": "integer", "question": "What was the spouse's age at the close of the taxable year?"},
